import{_ as d,o as s,c as a,a2 as e}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"第 1 章 ms-swift 是什么，为什么重要","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/01-what-is-ms-swift.md","filePath":"chapters/01-what-is-ms-swift.md"}'),r={name:"chapters/01-what-is-ms-swift.md"};function o(i,t,l,n,h,m){return s(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="第-1-章-ms-swift-是什么-为什么重要" tabindex="-1">第 1 章 ms-swift 是什么，为什么重要 <a class="header-anchor" href="#第-1-章-ms-swift-是什么-为什么重要" aria-label="Permalink to &quot;第 1 章 ms-swift 是什么，为什么重要&quot;">​</a></h1><h2 id="_1-1-从名字说起" tabindex="-1">1.1 从名字说起 <a class="header-anchor" href="#_1-1-从名字说起" aria-label="Permalink to &quot;1.1 从名字说起&quot;">​</a></h2><p><strong>ms-swift</strong> 是 ModelScope 团队开源的大模型微调与推理框架，全称为 &quot;ModelScope Swift&quot;。&quot;Swift&quot; 寓意&quot;快速&quot;，体现了框架的核心设计理念：让大模型的训练、微调、部署变得快速而简单。</p><p>作为阿里巴巴 ModelScope 生态的核心组件，ms-swift 提供了从数据准备到模型部署的完整工具链，支持 200+ 种主流大语言模型和多模态模型的微调与部署。</p><h2 id="_1-2-ms-swift-vs-其他微调框架" tabindex="-1">1.2 ms-swift vs 其他微调框架 <a class="header-anchor" href="#_1-2-ms-swift-vs-其他微调框架" aria-label="Permalink to &quot;1.2 ms-swift vs 其他微调框架&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>ms-swift</th><th>LLaMA-Factory</th><th>Axolotl</th></tr></thead><tbody><tr><td>模型支持</td><td>200+ 模型，多模态全覆盖</td><td>100+ 模型</td><td>50+ 模型</td></tr><tr><td>训练方法</td><td>SFT/RLHF/DPO/PPO/GRPO/GKD</td><td>SFT/RLHF/DPO</td><td>SFT/RLHF</td></tr><tr><td>分布式训练</td><td>DeepSpeed/FSDP/Megatron</td><td>DeepSpeed</td><td>DeepSpeed</td></tr><tr><td>推理加速</td><td>vLLM/LMDeploy/SGlang</td><td>vLLM</td><td>无</td></tr><tr><td>量化支持</td><td>GPTQ/AWQ/BNB</td><td>GPTQ/AWQ</td><td>GPTQ/AWQ</td></tr><tr><td>文档语言</td><td>中英文双版本</td><td>中英文</td><td>英文</td></tr></tbody></table><h2 id="_1-3-ms-swift-的三个核心特征" tabindex="-1">1.3 ms-swift 的三个核心特征 <a class="header-anchor" href="#_1-3-ms-swift-的三个核心特征" aria-label="Permalink to &quot;1.3 ms-swift 的三个核心特征&quot;">​</a></h2><p><strong>特征一：统一抽象层。</strong> ms-swift 通过 Template 系统统一了不同模型的输入格式，通过 ModelMeta 系统统一管理模型架构差异。开发者无需关心底层模型的具体实现，即可进行微调和推理。</p><p><strong>特征二：完整的 RLHF 支持。</strong> ms-swift 实现了 DPO、CPO、SimPO、ORPO、KTO、PPO、GRPO、GKD 等 9 种主流对齐算法，其中 DPO 支持 14 种损失函数变体。这是业界最完整的 RLHF 实现之一。</p><p><strong>特征三：灵活的扩展机制。</strong> 通过注册机制（register），开发者可以轻松添加自定义模型、数据集、损失函数、奖励函数。框架的模块化设计使得每个组件都可以独立替换。</p><h2 id="_1-4-发展历程" tabindex="-1">1.4 发展历程 <a class="header-anchor" href="#_1-4-发展历程" aria-label="Permalink to &quot;1.4 发展历程&quot;">​</a></h2><p>ms-swift 的发展经历了几个重要阶段：</p><ul><li><strong>v1.0（2023年初）</strong>：专注于 SFT 微调，支持 LoRA 和全参数训练</li><li><strong>v2.0（2023年中）</strong>：引入 RLHF 支持，新增 DPO、PPO 等对齐算法</li><li><strong>v3.0（2024年初）</strong>：重构架构，引入 Template 系统，支持多模态模型</li><li><strong>v3.5+（2024年中）</strong>：新增 GRPO、GKD 等前沿算法，支持 Megatron 集成</li></ul><h2 id="_1-5-实际用例" tabindex="-1">1.5 实际用例 <a class="header-anchor" href="#_1-5-实际用例" aria-label="Permalink to &quot;1.5 实际用例&quot;">​</a></h2><p><strong>用例一：企业私有化部署。</strong> 某金融企业使用 ms-swift 对 Qwen2.5-7B 进行 SFT 微调，使其掌握金融领域的专业术语和问答能力，然后通过 vLLM 部署为 API 服务。</p><p><strong>用例二：多模态模型训练。</strong> 某互联网公司使用 ms-swift 对 Qwen2-VL 进行多模态微调，使其能够理解和生成图文混合的内容。</p><p><strong>用例三：RLHF 对齐。</strong> 某研究机构使用 ms-swift 的 GRPO 算法对开源模型进行强化学习对齐，提升模型在数学推理任务上的表现。</p><h2 id="_1-6-与其他产品的定位对比" tabindex="-1">1.6 与其他产品的定位对比 <a class="header-anchor" href="#_1-6-与其他产品的定位对比" aria-label="Permalink to &quot;1.6 与其他产品的定位对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>定位</th><th>核心优势</th><th>适用场景</th></tr></thead><tbody><tr><td>ms-swift</td><td>全栈微调框架</td><td>完整工具链、丰富算法</td><td>生产级训练</td></tr><tr><td>LLaMA-Factory</td><td>轻量微调工具</td><td>上手快、文档好</td><td>快速实验</td></tr><tr><td>Axolotl</td><td>专业微调工具</td><td>灵活配置</td><td>研究探索</td></tr><tr><td>TRL</td><td>对齐训练库</td><td>HuggingFace 生态</td><td>学术研究</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>要点 1</strong>：ms-swift 是 ModelScope 团队开源的大模型微调框架，提供从训练到部署的完整工具链</li><li><strong>要点 2</strong>：统一抽象层、完整 RLHF 支持、灵活扩展机制是 ms-swift 的三大核心特征</li><li><strong>要点 3</strong>：ms-swift 适合需要生产级训练能力的企业用户和研究机构</li></ul>',21)])])}const c=d(r,[["render",o]]);export{p as __pageData,c as default};
